mapper.css:
body{
  margin:0;
  padding:0;
}

.slide{
  position:relative;
  width:1080px;
  height:1350px;
  overflow:hidden;
  font-family:'Inter',sans-serif;
  background:#0b0f14;
}

.bg{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:cover;
}

.shade{
  position:absolute;
  left:0;
  right:0;
  bottom:0;
  height:540px;
  background:linear-gradient(
    to top,
    rgba(4,10,18,.98) 0%,
    rgba(4,10,18,.88) 35%,
    rgba(4,10,18,.45) 70%,
    rgba(4,10,18,0) 100%
  );
}

.panel{
  position:absolute;
  left:0;
  right:0;
  bottom:0;
  padding:0 76px 155px 76px;
  background:transparent;
}

.logo{
  display:block;
  width:190px;
  height:auto;
  margin:0 0 12px -12px;
}

h1{
  margin:0;
  max-width:860px;
  font-size:50px;
  line-height:1.08;
  font-weight:700;
  letter-spacing:-1.5px;
  color:#ffffff;
}

.swipe{
  position:absolute;
  right:76px;
  bottom:105px;
  font-size:34px;
  line-height:1;
  letter-spacing:.5px;
  color:#ffffff;
  opacity:.92;
}

